.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 46px;
  padding: 0.7rem 1.2rem;
  background: var(--accent, #23604b);
  color: var(--on-accent, #faf9f2);
  border: 1px solid transparent;
  border-radius: 4px;
  font: 700 0.9rem/1.65 Manrope, sans-serif;
  text-decoration: none;
  white-space: nowrap;
}
.ds-button:hover {
  filter: brightness(0.9);
}
.ds-button:active {
  transform: translateY(1px);
}
.ds-button:focus-visible {
  outline: 3px solid var(--accent, #23604b);
  outline-offset: 5px;
}
@media (prefers-reduced-motion: no-preference) {
  .ds-button {
    transition: transform 160ms ease-out, filter 160ms ease-out;
  }
}

.ds-skills {
  --ink: #f3f1e7;
  --muted: #d8e2d5;
  --accent: #e6b74a;
  --on-accent: #233528;
  --paper: #355e4f;
  --rule: #749082;
  background: #23604b;
  color: var(--ink);
  font: 400 16px/1.65 Manrope, sans-serif;
}
.ds-filter {
  min-height: 44px;
  padding: 0.6rem 0.85rem;
  font: inherit;
  font-size: 0.85rem;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 4px;
  cursor: pointer;
}
.ds-filter:hover {
  border-color: var(--accent);
}
.ds-filter:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 5px;
}
.ds-filter[aria-pressed="true"] {
  background: var(--accent);
  color: var(--on-accent);
  border-color: var(--accent);
}

