.ds-skills {
  --ink: #f3f1e7;
  --muted: #d8e2d5;
  --accent: #e6b74a;
  --on-accent: #233528;
  --paper: #355e4f;
  --rule: #749082;
  background: #23604b;
  color: var(--ink);
  font: 400 16px/1.65 Manrope, sans-serif;
}
.ds-skill-tags {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.ds-skill-tags li {
  padding: 0.3rem 0.65rem;
  background: var(--paper);
  font-size: 0.9rem;
}

.ds-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  min-height: 64px;
  padding: 0.5rem 3vw;
  border-bottom: 1px solid var(--rule, #97a592);
  color: var(--ink, #183f32);
  font: 400 0.8rem/1.65 Manrope, sans-serif;
}
.ds-wordmark {
  color: inherit;
  font-weight: 700;
  text-decoration: none;
}
.ds-language-nav {
  display: flex;
  gap: 0.25rem;
  flex-shrink: 0;
}
.ds-language-nav a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  color: inherit;
  text-underline-offset: 0.25em;
}
.ds-header a:hover {
  text-decoration-thickness: 2px;
}
.ds-language-nav [aria-current="page"] {
  font-weight: 700;
  text-decoration-thickness: 3px;
}
.ds-header a:focus-visible {
  outline: 3px solid var(--accent, #23604b);
  outline-offset: 5px;
}
@media (max-width: 767px) {
  .ds-header {
    padding-inline: 1rem;
    gap: 0.75rem;
  }
}

.ds-disclosure {
  border-bottom: 1px solid var(--rule, #97a592);
  color: var(--ink, #183f32);
  font: 400 16px/1.65 Manrope, sans-serif;
}
.ds-disclosure summary {
  padding: 1.25rem 0.25rem;
  cursor: pointer;
  font-size: 1.12rem;
  font-weight: 600;
}
.ds-disclosure summary:hover {
  cursor: pointer;
}
.ds-disclosure summary:focus-visible {
  outline: 3px solid var(--accent, #23604b);
  outline-offset: 5px;
}
.ds-disclosure summary > span {
  display: inline-block;
  margin-left: 0.75rem;
  font-size: 0.8rem;
  font-weight: 400;
  color: var(--muted, #355547);
}
.ds-project-body {
  padding: 0.5rem 1.25rem 1.75rem;
}
.ds-project-body p {
  margin: 0;
  max-width: 70ch;
}
@media (max-width: 767px) {
  .ds-disclosure summary > span {
    display: block;
    margin: 0.25rem 0 0 1.1rem;
  }
}

.ds-route-map {
  position: relative;
  min-height: 400px;
  font: 400 16px/1.65 Manrope, sans-serif;
}
.ds-route-map svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.ds-land {
  fill: #23604b;
}
.ds-route {
  stroke: #d9d4c5;
  fill: none;
  stroke-width: 9;
}
.ds-route-progress {
  fill: none;
  stroke: #e6b74a;
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}
.ds-route-map:has(.ds-stop-skills:is(:hover, :focus-visible)) .ds-route-progress {
  stroke-dashoffset: 0.85;
}
.ds-route-map:has(.ds-stop-career:is(:hover, :focus-visible)) .ds-route-progress {
  stroke-dashoffset: 0.45;
}
.ds-route-map:has(.ds-stop-projects:is(:hover, :focus-visible)) .ds-route-progress {
  stroke-dashoffset: 0;
}
.ds-route-stop {
  position: absolute;
  display: flex;
  flex-direction: column;
  min-width: 116px;
  padding: 0.65rem 0.9rem;
  background: #e6b74a;
  color: #243528;
  font-size: 0.75rem;
  text-align: center;
  text-decoration: none;
  border-radius: 4px;
}
.ds-route-stop span {
  font-weight: 700;
  font-size: 1rem;
}
.ds-route-stop:focus-visible {
  outline: 3px solid #e6b74a;
  outline-offset: 5px;
}
.ds-stop-skills {
  left: 1%;
  bottom: 11%;
}
.ds-stop-career {
  left: 35%;
  top: 34%;
}
.ds-stop-projects {
  right: 0;
  top: 12%;
}
@media (prefers-reduced-motion: no-preference) {
  .ds-route {
    stroke-dasharray: 1;
    animation: ds-atlas-route 750ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .ds-route-progress {
    transition: stroke-dashoffset 420ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .ds-route-stop span {
    transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .ds-route-stop:is(:hover, :focus-visible) span {
    transform: translateY(-2px);
  }
  @keyframes ds-atlas-route {
    from { stroke-dashoffset: 1; }
    to { stroke-dashoffset: 0; }
  }
}
@media (max-width: 767px) {
  .ds-route-map {
    min-height: 290px;
  }
  .ds-route-stop {
    min-width: 98px;
    padding: 0.5rem;
  }
  .ds-route-stop span {
    font-size: 0.9rem;
  }
  .ds-stop-career {
    left: 33%;
  }
}
